LOGGER = logging.getLogger("translater")


def _setup_logging() -> None:
    try:
        log_dir = APP_DIR / "logs"
        log_dir.mkdir(parents=True, exist_ok=True)
        handler = RotatingFileHandler(
            log_dir / "translator.log", maxBytes=1_000_000, backupCount=2, encoding="utf-8"
        )
        logging.basicConfig(
            level=logging.INFO,
            handlers=[handler],
            format="%(asctime)s %(levelname)s %(name)s: %(message)s",
        )
    except OSError:
        pass


_ASSET_DIR = Path(__file__).resolve().parent / "assets" / "images"


def _asset(name: str) -> str:
    """Absolute path to a design image (works from any current directory)."""
    return str(_ASSET_DIR / name)


